import{_ as o,o as a,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const u=JSON.parse('{"title":"多 Bot 分工协作","description":"什么时候该拆成多个 Bot，怎么用群聊和交接让它们配合，以及如何避免重复劳动。","frontmatter":{"related":["/templates/team-content-studio","/templates/team-dev-squad","/automation/daily-briefing"],"title":"多 Bot 分工协作","description":"什么时候该拆成多个 Bot，怎么用群聊和交接让它们配合，以及如何避免重复劳动。","section":"automation","order":3,"tags":["自动化","多 Bot","协作","群聊"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/overview","https://x.ai/news/introducing-grok-bot"],"wordCount":608,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"多 Bot 分工协作 | WANGXXXL"}],["meta",{"property":"og:description","content":"什么时候该拆成多个 Bot，怎么用群聊和交接让它们配合，以及如何避免重复劳动。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/automation/multi-bot-teamwork"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/automation-multi-bot-teamwork-46a55242a8.png"}],["meta",{"property":"og:image:alt","content":"多 Bot 分工协作 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"多 Bot 分工协作 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"什么时候该拆成多个 Bot，怎么用群聊和交接让它们配合，以及如何避免重复劳动。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/automation-multi-bot-teamwork-46a55242a8.png"}],["meta",{"name":"twitter:image:alt","content":"多 Bot 分工协作 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/automation/multi-bot-teamwork"}]]},"headers":[],"relativePath":"automation/multi-bot-teamwork.md","filePath":"automation/multi-bot-teamwork.md","lastUpdated":1792485206000}'),s={name:"automation/multi-bot-teamwork.md"};function i(r,t,l,p,c,m){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="多-bot-分工协作" tabindex="-1">多 Bot 分工协作 <a class="header-anchor" href="#多-bot-分工协作" aria-label="Permalink to &quot;多 Bot 分工协作&quot;">​</a></h1><p>一个 Bot 能做很多事，但&quot;一个人包揽一切&quot;在 AI 身上同样会出问题：记忆混杂、上下文太长、边界不清。当工作量上来，就该像组建小团队一样，<strong>让几个 Bot 各管一摊</strong>。</p><h2 id="什么时候该拆" tabindex="-1">什么时候该拆 <a class="header-anchor" href="#什么时候该拆" aria-label="Permalink to &quot;什么时候该拆&quot;">​</a></h2><p>出现下面任一情况，就值得新建一个 Bot：</p><ul><li>目标不同（调研 vs 写作 vs 审核）；</li><li>用的工具不同（一个管邮箱，一个管代码仓库）；</li><li>风格或边界不同（一个可以大胆发散，一个必须严格保守）；</li><li>有独立的固定时间表。</li></ul><h2 id="协作的三种方式" tabindex="-1">协作的三种方式 <a class="header-anchor" href="#协作的三种方式" aria-label="Permalink to &quot;协作的三种方式&quot;">​</a></h2><p><strong>1. 群聊</strong>：新建对话时选择多个 Bot（数量有上限，以官方最新说明为准），说明共同目标和每人负责的环节。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@调研员 收集近一个月关于&quot;远程团队协作工具&quot;的公开资料，每条结论附链接。</span></span>
<span class="line"><span>@撰稿人 根据调研结果写一篇 1500 字的科普文章初稿。</span></span>
<span class="line"><span>@审稿人 对照来源核查初稿，只列出必须修改的问题。</span></span>
<span class="line"><span>全程不要发布任何内容。</span></span></code></pre></div><p>直接发消息时 Bot 们会自己判断谁来回应；用 <code>@</code> 可以指定某一位；<code>@everyone</code> 用于全员通知。</p><p><strong>2. Bot 之间直接交接</strong>：一个 Bot 可以给另一个 Bot 发消息，对方会被唤醒处理，并在之后回复。你能在对话里看到交接过程。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理完本周数据后，把汇总表交给&quot;周报助手&quot;，让它写成周报草稿。</span></span></code></pre></div><p><strong>3. 后台长任务</strong>：耗时很长的工作（比如批量处理几百个文件），Bot 可以放在后台推进，期间你照常和它对话，完成后再通知你。</p><h2 id="让协作不乱的规则" tabindex="-1">让协作不乱的规则 <a class="header-anchor" href="#让协作不乱的规则" aria-label="Permalink to &quot;让协作不乱的规则&quot;">​</a></h2><ul><li><strong>每个环节只有一个负责人</strong>。两个 Bot 同时做同一件事，只会产生重复成果和一堆噪音通知。</li><li><strong>交付物要明确</strong>：交给下一棒的是一个文件、一张表，还是一段结论？</li><li><strong>共享靠文件</strong>：所有 Bot 共用一台云电脑，约定好共享目录，比如 <code>/workspace/团队周报/</code>。</li></ul><div class="tip custom-block"><p class="custom-block-title">群聊的局限</p><p>群聊里不会出现审批卡片、登录请求和邮件草稿，这些只出现在一对一对话中。另外 Bot 在群里交接时目前只能传文字，需要看图的，让 Bot 直接把图片发给对方。</p></div><div class="warning custom-block"><p class="custom-block-title">多 Bot 不是权限隔离</p><p>所有 Bot 共享同一台电脑上的文件和登录状态。不要以为&quot;只有财务 Bot 知道这个密码&quot;——其他 Bot 一样能访问。</p></div><h2 id="从一个开始-慢慢扩" tabindex="-1">从一个开始，慢慢扩 <a class="header-anchor" href="#从一个开始-慢慢扩" aria-label="Permalink to &quot;从一个开始，慢慢扩&quot;">​</a></h2><p>不要第一天就建十个 Bot。建议从一个最常用的开始，发现它的工作明显分成两块时再拆。现成的组队方案可以参考团队模板。</p>`,18)])])}const g=o(s,[["render",i]]);export{u as __pageData,g as default};
